export function getOhFromYear(year: number): "목" | "화" | "토" | "금" | "수" {
  const GAN = ["경","신","임","계","갑","을","병","정","무","기"];
  const FROM_GAN: Record<string, "목"|"화"|"토"|"금"|"수"> = {
    갑:"목",을:"목",병:"화",정:"화",무:"토",기:"토",경:"금",신:"금",임:"수",계:"수"
  };
  return FROM_GAN[GAN[(year - 4) % 10]];
}
